207→
208→	// Use kimi defaults if agent config is not set
209→	if a.agentCfg.APIKey != "" && a.agentCfg.Model != "" {
210→		internal.LogDebug("Using configured model: %s", a.agentCfg.Model)
211→		session, err = agent.NewSession(
212→			agent.WithAPIKey(a.agentCfg.APIKey),
213→			agent.WithModel(a.agentCfg.Model),
214→			agent.WithWorkDir(a.workDir),
215→			agent.WithAutoApprove(),
216→			agent.WithMCPConfigFile(mcpFile),
217→			agent.WithSession(a.sessionID),
218→		)
219→	} else {
220→		internal.LogDebug("Using kimi default configuration")
221→		session, err = agent.NewSession(
222→			agent.WithWorkDir(a.workDir),
223→			agent.WithAutoApprove(),
224→			agent.WithMCPConfigFile(mcpFile),
225→			agent.WithSession(a.sessionID),
226→		)
227→	}
228→	if err != nil {
229→		return fmt.Errorf("failed to create session: %w", err)
230→	}
231→	defer session.Close()
232→
233→	// Build initial prompt
234→	contextPrompt := loadPrompt("context")
235→	analysePrompt := loadPrompt("analyse")
236→
237→	// Add batch info if multiple batches
238→	var batchInfo string
239→	if totalBatches > 1 {
240→		batchInfo = fmt.Sprintf("\n\n## Batch %d of %d\n\nThis is batch %d of %d. Previous batches have been processed. Focus on the files in this batch.", batchNum, totalBatches, batchNum, totalBatches)
241→	}
242→
243→	filesInfo := "\n\nChanged files (relative to working directory):\n" + strings.Join(files, "\n")
244→	initialPrompt := contextPrompt + "\n\n" + analysePrompt + batchInfo + filesInfo
245→
246→	// Send initial prompt
247→	internal.LogDebug("Batch %d/%d: sending initial prompt, files=%v", batchNum, totalBatches, files)
248→	start := time.Now()
249→	if err := a.runPrompt(ctx, session, initialPrompt); err != nil {
250→		internal.LogError("Batch %d/%d: initial prompt failed: %v", batchNum, totalBatches, err)
251→		return err
252→	}
253→	internal.LogDebug("Batch %d/%d: initial prompt completed, duration=%s", batchNum, totalBatches, time.Since(start))
254→
255→	// Validation loop
256→	maxRetries := 5
257→	for i := 0; i < maxRetries; i++ {
258→		internal.LogDebug("Validating .memo/index files (attempt %d/%d)", i+1, maxRetries)
259→		result := ValidateIndex(a.indexDir)
260→		if result.Valid {
261→			internal.LogInfo("Batch %d/%d validation passed", batchNum, totalBatches)
262→			return nil
263→		}
264→
265→		errMsg := FormatValidationErrors(result)
266→		internal.LogError("Batch %d/%d: validation failed (attempt %d/%d): %s", batchNum, totalBatches, i+1, maxRetries, errMsg)
267→
268→		// Send feedback prompt
269→		feedbackPrompt := loadPrompt("feedback")
270→		errorInfo := "Validation errors:\n" + FormatValidationErrors(result)
271→		fullFeedback := loadPrompt("context") + "\n\n" + feedbackPrompt + "\n\n" + errorInfo
272→
273→		internal.LogDebug("Batch %d/%d: sending feedback prompt (attempt %d)", batchNum, totalBatches, i+1)
274→		if err := a.runPrompt(ctx, session, fullFeedback); err != nil {
275→			internal.LogError("Batch %d/%d: feedback prompt failed: %v", batchNum, totalBatches, err)
276→			return err
277→		}
278→	}
279→
280→	return fmt.Errorf("validation failed after %d attempts", maxRetries)
281→}
282→
283→// maxCheckpointFileSize is the per-file truncation limit for checkpoint content.
284→// Large files (especially full.jsonl transcripts) are truncated to this size.
285→const maxCheckpointFileSize = 100 * 1024 // 100KB
286→
287→// maxCheckpointSize is the total content budget per checkpoint (all files combined).
288→const maxCheckpointSize = 300 * 1024 // 300KB
289→
290→// maxCheckpointBatchSize is the target maximum total content size per batch.
291→// Leaves room for prompt templates and API overhead within the 4MB API limit.
292→const maxCheckpointBatchSize = 2 * 1024 * 1024 // 2MB
293→
294→// truncateContent truncates content to maxLen bytes at a line boundary,
295→// appending a truncation notice.
296→func truncateContent(content string, maxLen int) string {
297→	if len(content) <= maxLen {
298→		return content
299→	}
300→	// Find last newline before maxLen
301→	cut := strings.LastIndex(content[:maxLen], "\n")
302→	if cut < 0 {
303→		cut = maxLen
304→	}
305→	return content[:cut] + "\n\n... [truncated, showing first " + fmt.Sprintf("%dKB", cut/1024) + " of " + fmt.Sprintf("%dKB", len(content)/1024) + "]"
306→}
307→
308→// skipCheckpointFile returns true for files that should be excluded from
309→// the analysis prompt. full.jsonl is redundant (context.md summarizes it)
310→// and content_hash.txt has no analytical value.
311→func skipCheckpointFile(path string) bool {
312→	base := filepath.Base(path)
313→	return base == "full.jsonl" || base == "content_hash.txt"
314→}
315→
316→// formatCheckpointData formats a single checkpoint's data for the prompt,
317→// skipping redundant files and truncating large ones.
318→func formatCheckpointData(cp CheckpointData, index int) string {
319→	var b strings.Builder
320→	b.WriteString(fmt.Sprintf("### Checkpoint %d: %s (commit: %s)\n\n", index, cp.CheckpointID, cp.CommitSHA[:8]))
321→
322→	remaining := maxCheckpointSize
323→	for path, content := range cp.Files {
324→		if skipCheckpointFile(path) {
325→			continue
326→		}
327→		if remaining <= 0 {
328→			b.WriteString("... [remaining files omitted, checkpoint budget exhausted]\n\n")
329→			break
330→		}
331→		fileLimit := maxCheckpointFileSize
332→		if remaining < fileLimit {
333→			fileLimit = remaining
334→		}
335→		content = truncateContent(content, fileLimit)
336→		b.WriteString(fmt.Sprintf("**File: %s**\n```\n%s\n```\n\n", path, content))
337→		remaining -= len(content)
338→	}
339→	return b.String()
340→}
341→
342→// batchCheckpoints groups checkpoints into batches where each batch's
343→// total formatted size stays under maxCheckpointBatchSize.
344→func batchCheckpoints(checkpoints []CheckpointData) [][]CheckpointData {
345→	var batches [][]CheckpointData
346→	var current []CheckpointData
347→	currentSize := 0
348→
349→	for i, cp := range checkpoints {
350→		formatted := formatCheckpointData(cp, i+1)
351→		fmtSize := len(formatted)
352→
353→		// If a single checkpoint exceeds the limit, it goes in its own batch
354→		if fmtSize >= maxCheckpointBatchSize {
355→			if len(current) > 0 {
356→				batches = append(batches, current)
357→				current = nil
358→				currentSize = 0
359→			}
360→			batches = append(batches, []CheckpointData{cp})
361→			continue
362→		}
363→
364→		if currentSize+fmtSize > maxCheckpointBatchSize && len(current) > 0 {
365→			batches = append(batches, current)
366→			current = nil
367→			currentSize = 0
368→		}
369→		current = append(current, cp)
370→		currentSize += fmtSize
371→	}
372→	if len(current) > 0 {
373→		batches = append(batches, current)
374→	}
375→	return batches
376→}
377→
378→// AnalyseCheckpoints analyses Entire.io checkpoint data and fuses insights
379→// into the existing 4 index files (arch, interface, stories, issues).
380→func (a *Analyser) AnalyseCheckpoints(ctx context.Context, checkpoints []CheckpointData) error {
381→	if len(checkpoints) == 0 {
382→		return nil
383→	}
384→
385→	batches := batchCheckpoints(checkpoints)
386→	internal.LogInfo("Analyzing %d checkpoint(s) into index files in %d batch(es)", len(checkpoints), len(batches))
387→
388→	// Mark status
389→	memoDir := filepath.Dir(a.indexDir)
390→	if err := SetStatus(memoDir, "analyzing"); err != nil {
391→		internal.LogError("Failed to set status: %v", err)
392→	}
393→	defer func() {
394→		if err := SetStatus(memoDir, "idle"); err != nil {
395→			internal.LogError("Failed to clear status: %v", err)
396→		}
397→	}()
398→
399→	for i, batch := range batches {
400→		if err := a.analyseCheckpointBatch(ctx, batch, i+1, len(batches)); err != nil {
401→			return err
402→		}
403→	}
404→	return nil
405→}
406→
407→func (a *Analyser) analyseCheckpointBatch(ctx context.Context, checkpoints []CheckpointData, batchNum, totalBatches int) error {
408→	internal.LogInfo("Processing checkpoint batch %d/%d (%d checkpoints)", batchNum, totalBatches, len(checkpoints))
409→
410→	// Build prompt with checkpoint data
411→	contextPrompt := loadPrompt("context")
412→	analysePrompt := loadPrompt("analyse_checkpoints")
413→
414→	var checkpointInfo strings.Builder
415→	checkpointInfo.WriteString("\n\n## Checkpoint Data\n\n")
416→	for i, cp := range checkpoints {
417→		checkpointInfo.WriteString(formatCheckpointData(cp, i+1))
418→	}
419→
420→	var batchInfo string
421→	if totalBatches > 1 {
422→		batchInfo = fmt.Sprintf("\n\n## Batch %d of %d\n\nThis is batch %d of %d. Previous batches have been processed. Focus on the checkpoints in this batch.\n", batchNum, totalBatches, batchNum, totalBatches)
423→	}
424→
425→	initialPrompt := contextPrompt + "\n\n" + analysePrompt + batchInfo + checkpointInfo.String()
426→	internal.LogDebug("Checkpoint batch %d/%d: prompt size=%dKB", batchNum, totalBatches, len(initialPrompt)/1024)
427→
428→	// Create agent session
429→	mcpFile := filepath.Join(a.workDir, ".memo", "mcp.json")
430→
431→	var session *agent.Session
432→	var err error
433→
434→	if a.agentCfg.APIKey != "" && a.agentCfg.Model != "" {
435→		session, err = agent.NewSession(
436→			agent.WithAPIKey(a.agentCfg.APIKey),
437→			agent.WithModel(a.agentCfg.Model),
438→			agent.WithWorkDir(a.workDir),
439→			agent.WithAutoApprove(),
440→			agent.WithMCPConfigFile(mcpFile),
441→			agent.WithSession(a.sessionID),
442→		)
443→	} else {
444→		session, err = agent.NewSession(
445→			agent.WithWorkDir(a.workDir),
446→			agent.WithAutoApprove(),
447→			agent.WithMCPConfigFile(mcpFile),
448→			agent.WithSession(a.sessionID),
449→		)
450→	}
451→	if err != nil {
452→		return fmt.Errorf("failed to create session: %w", err)
453→	}
454→	defer session.Close()
455→
456→	// Send prompt
457→	internal.LogDebug("Checkpoint batch %d/%d: sending prompt for %d checkpoints", batchNum, totalBatches, len(checkpoints))
458→	start := time.Now()
459→	if err := a.runPrompt(ctx, session, initialPrompt); err != nil {
460→		return fmt.Errorf("checkpoint batch %d/%d failed: %w", batchNum, totalBatches, err)
461→	}
462→	internal.LogDebug("Checkpoint batch %d/%d completed, duration=%s", batchNum, totalBatches, time.Since(start))
463→
464→	// Validation loop (reuse existing ValidateIndex for the 4 files)
465→	maxRetries := 5
466→	for i := 0; i < maxRetries; i++ {
467→		result := ValidateIndex(a.indexDir)
468→		if result.Valid {
469→			internal.LogInfo("Checkpoint batch %d/%d validation passed", batchNum, totalBatches)
470→			return nil
471→		}
472→
473→		errMsg := FormatValidationErrors(result)
474→		internal.LogError("Checkpoint batch %d/%d validation failed (attempt %d/%d): %s", batchNum, totalBatches, i+1, maxRetries, errMsg)
475→
476→		feedbackPrompt := loadPrompt("feedback")
477→		errorInfo := "Validation errors:\n" + errMsg
478→		fullFeedback := loadPrompt("context") + "\n\n" + feedbackPrompt + "\n\n" + errorInfo
479→
480→		if err := a.runPrompt(ctx, session, fullFeedback); err != nil {
481→			return fmt.Errorf("checkpoint batch %d/%d feedback failed: %w", batchNum, totalBatches, err)
482→		}
483→	}
484→
485→	return fmt.Errorf("checkpoint batch %d/%d validation failed after %d attempts", batchNum, totalBatches, maxRetries)
486→}
487→
488→func (a *Analyser) runPrompt(ctx context.Context, session *agent.Session, prompt string) error {
489→	turn, err := session.Prompt(ctx, wire.NewStringContent(prompt))
490→	if err != nil {
491→		return fmt.Errorf("prompt failed: %w", err)
492→	}
493→
494→	lb := internal.NewLineBuffer(500 * time.Millisecond)
495→
496→	// Consume all messages
497→	for step := range turn.Steps {
498→		for msg := range step.Messages {
499→			switch m := msg.(type) {
500→			case wire.ApprovalRequest:
501→				internal.LogDebug("Auto-approving request")
502→				_ = m.Respond(wire.ApprovalRequestResponseApprove)
503→			case wire.ContentPart:
504→				if m.Type == wire.ContentPartTypeText && m.Text.Valid {
505→					lb.Write(m.Text.Value)
506→					if lines := lb.Flush(false); lines != "" {
507→						internal.LogDebug("Agent output: %s", lines)
508→					}
509→				}
510→			case wire.StatusUpdate:
511→				// StatusUpdate usually means a generation round is complete
512→				if lines := lb.Flush(true); lines != "" {
513→					internal.LogDebug("Agent output: %s", lines)
514→				}
515→			}
516→		}
517→		// Step ended, force flush remaining content
518→		if lines := lb.Flush(true); lines != "" {
519→			internal.LogDebug("Agent output: %s", lines)
520→		}
521→	}
522→
523→	if err := turn.Err(); err != nil {
524→		return fmt.Errorf("turn error: %w", err)
525→	}
526→
527→	return nil
528→}
