  1→package analyzer
  2→
  3→import (
  4→	"errors"
  5→	"io/fs"
  6→	"os"
  7→	"path/filepath"
  8→
  9→	"sync"
 10→	"time"
 11→
 12→	"github.com/YoungY620/memo/internal"
 13→	"github.com/fsnotify/fsnotify"
 14→)
 15→
 16→type Watcher struct {
 17→	debounceMs, maxWaitMs int
 18→	matcher               *GitignoreMatcher
 19→	onChange              func([]string)
 20→	watcher               *fsnotify.Watcher
 21→	rootPath              string
 22→
 23→	mu                sync.Mutex
 24→	pending           map[string]struct{}
 25→	debounce, maxWait *time.Timer
 26→	sem               chan struct{} // capacity 1 semaphore for analysis guard
 27→}
 28→
 29→// describePathError extracts detailed information from filesystem errors (cross-platform)
 30→func describePathError(err error) (op, path, reason string) {
 31→	var pathErr *fs.PathError
 32→	if !errors.As(err, &pathErr) {
 33→		return "", "", err.Error()
 34→	}
 35→
 36→	op = pathErr.Op
 37→	path = pathErr.Path
 38→
 39→	// Use cross-platform error checks from io/fs package
 40→	switch {
 41→	case errors.Is(err, fs.ErrNotExist):
 42→		reason = "no such file or directory (broken symlink?)"
 43→	case errors.Is(err, fs.ErrPermission):
 44→		reason = "permission denied"
 45→	case errors.Is(err, fs.ErrInvalid):
 46→		reason = "invalid argument"
 47→	case errors.Is(err, fs.ErrClosed):
 48→		reason = "file already closed"
 49→	default:
 50→		reason = pathErr.Err.Error()
 51→	}
 52→
 53→	return op, path, reason
 54→}
 55→
 56→func NewWatcher(root string, globalPatterns []string, debounceMs, maxWaitMs int, onChange func([]string)) (*Watcher, error) {
 57→	fsw, err := fsnotify.NewWatcher()
 58→	if err != nil {
 59→		return nil, err
 60→	}
 61→
 62→	// Create gitignore matcher BEFORE watchAll
 63→	matcher, err := NewGitignoreMatcher(root, globalPatterns)
 64→	if err != nil {
 65→		fsw.Close()
 66→		return nil, err
 67→	}
 68→
 69→	w := &Watcher{
 70→		rootPath:   root,
 71→		matcher:    matcher,
 72→		debounceMs: debounceMs,
 73→		maxWaitMs:  maxWaitMs,
 74→		onChange:   onChange,
 75→		watcher:    fsw,
 76→		pending:    make(map[string]struct{}),
 77→		sem:        make(chan struct{}, 1),
 78→	}
 79→	if err := w.watchAll(root); err != nil {
 80→		fsw.Close()
 81→		return nil, err
 82→	}
 83→	return w, nil
 84→}
 85→
 86→func (w *Watcher) watchAll(dir string) error {
 87→	return filepath.WalkDir(dir, func(p string, d os.DirEntry, err error) error {
 88→		if err != nil {
 89→			op, path, reason := describePathError(err)
 90→			internal.LogWarning("Skipping path: op=%s, path=%s, reason=%s", op, path, reason)
 91→			return nil
 92→		}
 93→		if !d.IsDir() {
 94→			return nil
 95→		}
 96→		if w.matcher.Match(p) {
 97→			return filepath.SkipDir
 98→		}
 99→		if err := w.watcher.Add(p); err != nil {
100→			op, path, reason := describePathError(err)
101→			internal.LogWarning("Cannot add watch: op=%s, path=%s, reason=%s", op, path, reason)
102→		}
103→		return nil
104→	})
105→}
106→
107→// ScanAll traverses all files and adds them to pending, triggering initial analysis
108→func (w *Watcher) ScanAll() {
109→	count := 0
110→	_ = filepath.WalkDir(w.rootPath, func(p string, d os.DirEntry, err error) error {
111→		if err != nil || d.IsDir() {
112→			return err
113→		}
114→		if w.matcher.Match(p) {
115→			return nil
116→		}
117→		w.add(p)
118→		count++
119→		return nil
120→	})
121→	internal.LogDebug("ScanAll: added %d files to pending", count)
122→}
123→
124→
125→
126→func (w *Watcher) Run() error {
127→	for {
128→		select {
129→		case e, ok := <-w.watcher.Events:
130→			if !ok {
131→				return nil
132→			}
133→
134→			// Handle .gitignore file changes
135→			if filepath.Base(e.Name) == ".gitignore" {
136→				if e.Op&fsnotify.Write != 0 || e.Op&fsnotify.Create != 0 {
137→					internal.LogInfo(".gitignore changed: %s", e.Name)
138→					if err := w.matcher.AddGitignore(e.Name); err != nil {
139→						internal.LogWarning("Failed to reload .gitignore: %v", err)
140→					}
141→				} else if e.Op&fsnotify.Remove != 0 {
142→					w.matcher.RemoveGitignore(e.Name)
143→				}
144→				continue
145→			}
146→
147→			if w.matcher.Match(e.Name) {
148→				continue
149→			}
150→			internal.LogDebug("Event: %s %s", e.Op, e.Name)
151→			if e.Op&fsnotify.Create != 0 {
152→				if info, err := os.Stat(e.Name); err == nil && info.IsDir() {
153→					internal.LogDebug("Watching new directory: %s", e.Name)
154→					_ = w.watcher.Add(e.Name)
155→				}
156→			}
157→			if e.Op&(fsnotify.Write|fsnotify.Create|fsnotify.Remove|fsnotify.Rename) != 0 {
158→				w.add(e.Name)
159→			}
160→		case err, ok := <-w.watcher.Errors:
161→			if !ok {
162→				return nil
163→			}
164→			if err != nil {
165→				internal.LogError("Watcher error: %v", err)
166→			}
167→		}
168→	}
169→}
170→
171→func (w *Watcher) add(file string) {
172→	w.mu.Lock()
173→	defer w.mu.Unlock()
174→
175→	first := len(w.pending) == 0
176→	w.pending[file] = struct{}{}
177→
178→	// Reset debounce timer
179→	if w.debounce != nil {
180→		w.debounce.Stop()
181→	}
182→	w.debounce = time.AfterFunc(time.Duration(w.debounceMs)*time.Millisecond, w.Flush)
183→
184→	// Start max wait timer on first change
185→	if first {
186→		w.maxWait = time.AfterFunc(time.Duration(w.maxWaitMs)*time.Millisecond, w.Flush)
187→	}
188→}
189→
190→func (w *Watcher) Flush() {
191→	// Non-blocking acquire: skip if analysis already running
192→	select {
193→	case w.sem <- struct{}{}:
194→		// acquired
195→	default:
196→		internal.LogDebug("Analysis in progress, skipping flush (files remain in pending)")
197→		return
198→	}
199→	defer func() { <-w.sem }()
200→
201→	w.mu.Lock()
202→	if w.debounce != nil {
203→		w.debounce.Stop()
204→		w.debounce = nil
205→	}
206→	if w.maxWait != nil {
207→		w.maxWait.Stop()
208→		w.maxWait = nil
209→	}
210→	files := make([]string, 0, len(w.pending))
211→	for f := range w.pending {
212→		files = append(files, f)
213→	}
214→	w.pending = make(map[string]struct{})
215→	w.mu.Unlock()
216→
217→	if len(files) > 0 && w.onChange != nil {
218→		w.onChange(files)
219→	}
220→}
221→
222→func (w *Watcher) Close() error {
223→	w.mu.Lock()
224→	if w.debounce != nil {
225→		w.debounce.Stop()
226→	}
227→	if w.maxWait != nil {
228→		w.maxWait.Stop()
229→	}
230→	w.mu.Unlock()
231→	return w.watcher.Close()
232→}
