 12→var scanCmd = &cobra.Command{
 13→	Use:   "scan",
 14→	Short: "Scan mode - analyzes all files once, updates index, then exits",
 15→	Long:  `Analyzes all files in the codebase once, updates .memo/index, then exits. Useful for CI or initial setup.`,
 16→	RunE:  runScan,
 17→}
 18→
 19→func init() {
 20→	scanCmd.Flags().StringVarP(&configFlag, "config", "c", "config.yaml", "config file path")
 21→	rootCmd.AddCommand(scanCmd)
 22→}
 23→
 24→func runScan(cmd *cobra.Command, args []string) error {
 25→	workDir, err := resolveWorkDir()
 26→	if err != nil {
 27→		return err
 28→	}
 29→
 30→	cfg, err := loadConfigAndSetup(workDir)
 31→	if err != nil {
 32→		return err
 33→	}
 34→
 35→	// Initialize .memo/index directory
 36→	indexDir := filepath.Join(workDir, ".memo", "index")
 37→	if err := initIndex(indexDir); err != nil {
 38→		return err
 39→	}
 40→	internal.LogDebug("Initialized .memo/index directory: %s", indexDir)
 41→
 42→	// Acquire single instance lock
 43→	memoDir := filepath.Join(workDir, ".memo")
 44→	lockFile, err := analyzer.TryLock(memoDir)
 45→	if err != nil {
 46→		return err
 47→	}
 48→	defer analyzer.Unlock(lockFile)
 49→
 50→	// Initialize history logger
 51→	internal.InitHistoryLogger(memoDir, "watcher")
 52→	defer internal.CloseHistoryLogger()
 53→
 54→	// Ensure status is idle on startup and exit
 55→	if err := analyzer.SetStatus(memoDir, "idle"); err != nil {
 56→		internal.LogError("Failed to set initial status: %v", err)
 57→	}
 58→	defer func() {
 59→		if err := analyzer.SetStatus(memoDir, "idle"); err != nil {
 60→			internal.LogError("Failed to reset status on exit: %v", err)
 61→		}
 62→	}()
 63→
 64→	// Create analyser
 65→	agentCfg := analyzer.AgentConfig{
 66→		APIKey: cfg.Agent.APIKey,
 67→		Model:  cfg.Agent.Model,
 68→	}
 69→	ana := analyzer.NewAnalyser(agentCfg, workDir)
 70→
 71→	// Create watcher (reuse for scanning logic)
 72→	watcher, err := analyzer.NewWatcher(workDir, cfg.Watch.IgnorePatterns, cfg.Watch.DebounceMs, cfg.Watch.MaxWaitMs, func(files []string) {
 73→		internal.LogInfo("Triggered with %d changed files", len(files))
 74→		internal.LogDebug("Changed files: %v", files)
 75→		ctx := context.Background()
 76→		if err := ana.Analyse(ctx, files); err != nil {
 77→			internal.LogError("Analysis failed: %v", err)
 78→		}
 79→	})
 80→	if err != nil {
 81→		return err
 82→	}
 83→	defer watcher.Close()
 84→
 85→	// Start async update check
 86→	updateCh := internal.CheckUpdateAsync(Version)
 87→
 88→	// Print banner
 89→	var updateInfo *analyzer.UpdateInfo
 90→	select {
 91→	case result := <-updateCh:
 92→		if result != nil {
 93→			updateInfo = &analyzer.UpdateInfo{
 94→				LatestVersion: result.LatestVersion,
 95→				UpdateCommand: result.UpdateCommand,
 96→			}
 97→		}
 98→	default:
 99→		// Update check not ready yet, continue without it
100→	}
101→
102→	analyzer.PrintBanner(analyzer.BannerOptions{
103→		WorkDir:    workDir,
104→		Version:    Version,
105→		UpdateInfo: updateInfo,
106→	})
107→
108→	// Scan all files
109→	internal.LogInfo("Scanning all files, workDir=%s", workDir)
110→	watcher.ScanAll()
111→	internal.LogDebug("Scan completed")
112→
113→	// Flush and exit
114→	watcher.Flush()
115→
116→	// Entire.io checkpoint scanning
117→	entireCfg, _ := analyzer.DetectEntire(workDir)
118→	if entireCfg != nil && entireCfg.Enabled {
119→		internal.LogInfo("Entire.io detected (strategy=%s), scanning checkpoints", entireCfg.Strategy)
120→
121→		cpMon, err := analyzer.NewCheckpointMonitor(workDir, cfg.Watch.DebounceMs, nil)
122→		if err != nil {
123→			internal.LogError("Failed to create checkpoint monitor: %v", err)
124→		} else {
125→			cps, err := cpMon.ScanAll()
126→			if err != nil {
127→				internal.LogError("Checkpoint scan failed: %v", err)
128→			} else if len(cps) > 0 {
129→				ctx := context.Background()
130→				if err := ana.AnalyseCheckpoints(ctx, cps); err != nil {
131→					internal.LogError("Checkpoint analysis failed: %v", err)
132→				}
133→			}
134→			cpMon.Close()
135→		}
136→	}
137→
138→	internal.LogInfo("Scan mode completed")
139→	return nil
140→}
