  1→package internal
  2→
  3→import (
  4→	"encoding/json"
  5→	"fmt"
  6→	"os"
  7→	"path/filepath"
  8→	"sync"
  9→	"time"
 10→)
 11→
 12→// HistoryLogger logs events to .memo/.history for debugging
 13→type HistoryLogger struct {
 14→	file   *os.File
 15→	mu     sync.Mutex
 16→	seqNum int64
 17→	source string
 18→}
 19→
 20→// HistoryEntry represents a single log entry
 21→type HistoryEntry struct {
 22→	Seq       int64  `json:"seq"`
 23→	Timestamp string `json:"ts"`
 24→	Source    string `json:"src"`              // "mcp" or "watcher"
 25→	Type      string `json:"type"`             // "request", "response", "error", "info", "debug"
 26→	Method    string `json:"method,omitempty"` // for mcp requests
 27→	ID        any    `json:"id,omitempty"`     // for mcp request/response correlation
 28→	Params    any    `json:"params,omitempty"`
 29→	Result    any    `json:"result,omitempty"`
 30→	Error     any    `json:"error,omitempty"`
 31→	Duration  string `json:"duration,omitempty"`
 32→	Message   string `json:"msg,omitempty"`
 33→}
 34→
 35→// NewHistoryLogger creates a new history logger with given source
 36→func NewHistoryLogger(memoDir, source string) (*HistoryLogger, error) {
 37→	historyPath := filepath.Join(memoDir, ".history")
 38→	f, err := os.OpenFile(historyPath, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0644)
 39→	if err != nil {
 40→		return nil, fmt.Errorf("failed to open history file: %w", err)
 41→	}
 42→	return &HistoryLogger{file: f, source: source}, nil
 43→}
 44→
 45→// Log writes an entry to the history file
 46→func (h *HistoryLogger) Log(entry HistoryEntry) {
 47→	if h == nil || h.file == nil {
 48→		return
 49→	}
 50→	h.mu.Lock()
 51→	defer h.mu.Unlock()
 52→
 53→	h.seqNum++
 54→	entry.Seq = h.seqNum
 55→	entry.Timestamp = time.Now().Format(time.RFC3339Nano)
 56→	entry.Source = h.source
 57→
 58→	data, err := json.Marshal(entry)
 59→	if err != nil {
 60→		return
 61→	}
 62→	_, _ = h.file.Write(data)
 63→	_, _ = h.file.Write([]byte("\n"))
 64→}
 65→
 66→// LogError logs an error
 67→func (h *HistoryLogger) LogError(message string, err error) {
 68→	entry := HistoryEntry{Type: "error", Message: message}
 69→	if err != nil {
 70→		entry.Error = err.Error()
 71→	}
 72→	h.Log(entry)
 73→}
 74→
 75→// LogInfo logs an informational message
 76→func (h *HistoryLogger) LogInfo(format string, v ...any) {
 77→	msg := format
 78→	if len(v) > 0 {
 79→		msg = fmt.Sprintf(format, v...)
 80→	}
 81→	h.Log(HistoryEntry{Type: "info", Message: msg})
 82→}
 83→
 84→// LogDebug logs a debug message
 85→func (h *HistoryLogger) LogDebug(format string, v ...any) {
 86→	msg := format
 87→	if len(v) > 0 {
 88→		msg = fmt.Sprintf(format, v...)
 89→	}
 90→	h.Log(HistoryEntry{Type: "debug", Message: msg})
 91→}
 92→
 93→// Close closes the history file
 94→func (h *HistoryLogger) Close() error {
 95→	if h != nil && h.file != nil {
 96→		return h.file.Close()
 97→	}
 98→	return nil
 99→}
