  1→package cmd
  2→
  3→import (
  4→	"context"
  5→	"os"
  6→	"os/signal"
  7→	"path/filepath"
  8→	"syscall"
  9→
 10→	"github.com/YoungY620/memo/analyzer"
 11→	"github.com/YoungY620/memo/internal"
 12→	"github.com/spf13/cobra"
 13→)
 14→
 15→var (
 16→	skipScan bool
 17→)
 18→
 19→var watchCmd = &cobra.Command{
 20→	Use:   "watch",
 21→	Short: "Watch mode - monitors file changes and updates index continuously",
 22→	Long:  `Continuously monitors file changes and updates .memo/index. This is the default command.`,
 23→	RunE:  runWatch,
 24→}
 25→
 26→func init() {
 27→	watchCmd.Flags().StringVarP(&configFlag, "config", "c", "config.yaml", "config file path")
 28→	watchCmd.Flags().BoolVar(&skipScan, "skip-scan", false, "skip initial full scan")
 29→	rootCmd.AddCommand(watchCmd)
 30→
 31→	// Set watch as the default command when no subcommand is provided
 32→	rootCmd.RunE = func(cmd *cobra.Command, args []string) error {
 33→		return runWatch(cmd, args)
 34→	}
 35→}
 36→
 37→func runWatch(cmd *cobra.Command, args []string) error {
 38→	workDir, err := resolveWorkDir()
 39→	if err != nil {
 40→		return err
 41→	}
 42→
 43→	cfg, err := loadConfigAndSetup(workDir)
 44→	if err != nil {
 45→		return err
 46→	}
 47→
 48→	// Initialize .memo/index directory
 49→	indexDir := filepath.Join(workDir, ".memo", "index")
 50→	if err := initIndex(indexDir); err != nil {
 51→		return err
 52→	}
 53→	internal.LogDebug("Initialized .memo/index directory: %s", indexDir)
 54→
 55→	// Acquire single instance lock
 56→	memoDir := filepath.Join(workDir, ".memo")
 57→	lockFile, err := analyzer.TryLock(memoDir)
 58→	if err != nil {
 59→		return err
 60→	}
 61→	defer analyzer.Unlock(lockFile)
 62→
 63→	// Initialize history logger
 64→	internal.InitHistoryLogger(memoDir, "watcher")
 65→	defer internal.CloseHistoryLogger()
 66→
 67→	// Ensure status is idle on startup and exit
 68→	if err := analyzer.SetStatus(memoDir, "idle"); err != nil {
 69→		internal.LogError("Failed to set initial status: %v", err)
 70→	}
 71→	defer func() {
 72→		if err := analyzer.SetStatus(memoDir, "idle"); err != nil {
 73→			internal.LogError("Failed to reset status on exit: %v", err)
 74→		}
 75→	}()
 76→
 77→	// Create analyser
 78→	agentCfg := analyzer.AgentConfig{
 79→		APIKey: cfg.Agent.APIKey,
 80→		Model:  cfg.Agent.Model,
 81→	}
 82→	ana := analyzer.NewAnalyser(agentCfg, workDir)
 83→
 84→	// Create watcher
 85→	watcher, err := analyzer.NewWatcher(workDir, cfg.Watch.IgnorePatterns, cfg.Watch.DebounceMs, cfg.Watch.MaxWaitMs, func(files []string) {
 86→		internal.LogInfo("Triggered with %d changed files", len(files))
 87→		internal.LogDebug("Changed files: %v", files)
 88→		ctx := context.Background()
 89→		if err := ana.Analyse(ctx, files); err != nil {
 90→			internal.LogError("Analysis failed: %v", err)
 91→		}
 92→	})
 93→	if err != nil {
 94→		return err
 95→	}
 96→	defer watcher.Close()
 97→
 98→	// Start async update check
 99→	updateCh := internal.CheckUpdateAsync(Version)
100→
101→	// Print banner
102→	var updateInfo *analyzer.UpdateInfo
103→	select {
104→	case result := <-updateCh:
105→		if result != nil {
106→			updateInfo = &analyzer.UpdateInfo{
107→				LatestVersion: result.LatestVersion,
108→				UpdateCommand: result.UpdateCommand,
109→			}
110→		}
111→	default:
112→		// Update check not ready yet, continue without it
113→	}
114→
115→	analyzer.PrintBanner(analyzer.BannerOptions{
116→		WorkDir:    workDir,
117→		Version:    Version,
118→		UpdateInfo: updateInfo,
119→	})
120→
121→	// Entire.io checkpoint monitoring
122→	entireCfg, _ := analyzer.DetectEntire(workDir)
123→	if entireCfg != nil && entireCfg.Enabled {
124→		internal.LogInfo("Entire.io detected (strategy=%s)", entireCfg.Strategy)
125→
126→		cpMon, err := analyzer.NewCheckpointMonitor(workDir, cfg.Watch.DebounceMs, func(cps []analyzer.CheckpointData) {
127→			ctx := context.Background()
128→			if err := ana.AnalyseCheckpoints(ctx, cps); err != nil {
129→				internal.LogError("Checkpoint analysis failed: %v", err)
130→			}
131→		})
132→		if err != nil {
133→			internal.LogError("Failed to create checkpoint monitor: %v", err)
134→		} else {
135→			defer cpMon.Close()
136→
137→			if !skipScan {
138→				cps, err := cpMon.ScanAll()
139→				if err != nil {
140→					internal.LogError("Checkpoint scan failed: %v", err)
141→				} else if len(cps) > 0 {
142→					ctx := context.Background()
143→					if err := ana.AnalyseCheckpoints(ctx, cps); err != nil {
144→						internal.LogError("Checkpoint analysis failed: %v", err)
145→					}
146→				}
147→			}
148→
149→			go func() {
150→				if err := cpMon.Run(); err != nil {
151→					internal.LogError("Checkpoint monitor error: %v", err)
152→				}
153→			}()
154→		}
155→	}
156→
157→	// Initial scan (unless --skip-scan is set)
158→	internal.LogInfo("Watcher started, workDir=%s", workDir)
159→	if !skipScan {
160→		watcher.ScanAll()
161→		internal.LogDebug("Initial scan completed")
162→	} else {
163→		internal.LogInfo("Skipping initial scan (--skip-scan)")
164→	}
165→
166→	// Watch mode
167→	internal.LogInfo("Memo watching: %s", workDir)
168→
169→	// Handle shutdown
170→	sigChan := make(chan os.Signal, 1)
171→	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
172→
173→	go func() {
174→		if err := watcher.Run(); err != nil {
175→			internal.LogError("Watcher error: %v", err)
176→		}
177→	}()
178→
179→	<-sigChan
180→	internal.LogInfo("Shutting down...")
181→	return nil
182→}
