140→// ValidationResult holds the result of index validation
141→type ValidationResult struct {
142→	Valid  bool
143→	Errors []string
144→}
145→
146→// ValidateIndex validates all JSON files in the index directory
147→func ValidateIndex(indexDir string) ValidationResult {
148→	var allErrors []string
149→
150→	for filename, schemaJSON := range schemas {
151→		filePath := filepath.Join(indexDir, filename)
152→		data, err := os.ReadFile(filePath)
153→		if err != nil {
154→			allErrors = append(allErrors, fmt.Sprintf("%s: %v", filename, err))
155→			continue
156→		}
157→
158→		schemaLoader := gojsonschema.NewStringLoader(schemaJSON)
159→		documentLoader := gojsonschema.NewBytesLoader(data)
160→
161→		result, err := gojsonschema.Validate(schemaLoader, documentLoader)
162→		if err != nil {
163→			allErrors = append(allErrors, fmt.Sprintf("%s: schema validation error: %v", filename, err))
164→			continue
165→		}
166→
167→		if !result.Valid() {
168→			for _, e := range result.Errors() {
169→				allErrors = append(allErrors, fmt.Sprintf("%s: %s", filename, e.String()))
170→			}
171→		}
172→	}
173→
174→	return ValidationResult{
175→		Valid:  len(allErrors) == 0,
176→		Errors: allErrors,
177→	}
178→}
179→
180→// FormatValidationErrors formats validation errors as a string
181→func FormatValidationErrors(result ValidationResult) string {
182→	if result.Valid {
183→		return ""
184→	}
185→	return strings.Join(result.Errors, "\n")
186→}
