106→// NewServer creates a new MCP server
107→func NewServer(workDir string) *Server {
108→	memoDir := filepath.Join(workDir, ".memo")
109→	// Ensure .memo directory exists
110→	_ = os.MkdirAll(memoDir, 0755)
111→
112→	h, _ := internal.NewHistoryLogger(memoDir, "mcp") // ignore error, logging is optional
113→
114→	return &Server{
115→		indexDir: filepath.Join(memoDir, "index"),
116→		memoDir:  memoDir,
