123→// logRequest logs an incoming MCP request
124→func (s *Server) logRequest(req *Request) {
125→	if s.history == nil {
126→		return
127→	}
128→	var params any
129→	if len(req.Params) > 0 {
130→		_ = json.Unmarshal(req.Params, &params)
131→	}
132→	s.history.Log(internal.HistoryEntry{
133→		Type:   "request",
134→		Method: req.Method,
135→		ID:     req.ID,
136→		Params: params,
137→	})
138→}
