140→// logResponse logs an outgoing MCP response
141→func (s *Server) logResponse(resp *Response, duration time.Duration) {
142→	if s.history == nil {
143→		return
144→	}
145→	entry := internal.HistoryEntry{
146→		Type:     "response",
147→		ID:       resp.ID,
148→		Duration: duration.String(),
149→	}
150→	if resp.Error != nil {
151→		entry.Error = resp.Error
152→	} else {
153→		entry.Result = resp.Result
154→	}
155→	s.history.Log(entry)
156→}
