161→	data, err := os.ReadFile(path)
162→	if err != nil {
163→		return Status{Status: "idle"}
164→	}
165→	var status Status
166→	if err := json.Unmarshal(data, &status); err != nil {
167→		return Status{Status: "idle"}
168→	}
169→	return status
