222→// Run starts the MCP server
223→func (s *Server) Run() error {
224→	if s.history != nil {
225→		s.history.LogInfo("MCP server started")
226→		defer s.history.Close()
227→		defer s.history.LogInfo("MCP server stopped")
228→	}
229→
230→	for {
231→		line, err := s.reader.ReadBytes('\n')
232→		if err != nil {
233→			if err == io.EOF {
234→				return nil
235→			}
236→			if s.history != nil {
237→				s.history.LogError("read error", err)
238→			}
239→			return err
240→		}
241→
242→		var req Request
243→		if err := json.Unmarshal(line, &req); err != nil {
244→			if s.history != nil {
245→				s.history.LogError("parse error", err)
246→			}
247→			s.sendError(nil, -32700, "Parse error")
248→			continue
249→		}
250→
251→		// Log request
252→		s.logRequest(&req)
253→
254→		start := time.Now()
255→		resp := s.handleRequest(&req)
256→		duration := time.Since(start)
257→
258→		if resp != nil {
259→			// Log response
260→			s.logResponse(resp, duration)
261→			s.sendResponse(resp)
262→		}
263→	}
264→}
265→
266→func (s *Server) handleRequest(req *Request) *Response {
267→	switch req.Method {
268→	case "initialize":
269→		return &Response{
270→			JSONRPC: "2.0",
271→			ID:      req.ID,
272→			Result: InitializeResult{
273→				ProtocolVersion: "2024-11-05",
274→				ServerInfo: ServerInfo{
275→					Name:    "memo",
276→					Version: "1.0.0",
277→				},
278→				Capabilities: Capabilities{
279→					Tools: &ToolsCapability{},
280→				},
281→			},
282→		}
283→
284→	case "notifications/initialized":
285→		// No response needed for notifications
286→		return nil
287→
288→	case "tools/list":
289→		return &Response{
290→			JSONRPC: "2.0",
291→			ID:      req.ID,
292→			Result:  ToolsListResult{Tools: s.tools()},
293→		}
294→
295→	case "tools/call":
296→		var params ToolCallParams
297→		if err := json.Unmarshal(req.Params, &params); err != nil {
298→			return s.errorResponse(req.ID, -32602, "Invalid params")
299→		}
300→		return s.handleToolCall(req.ID, &params)
301→
302→	default:
303→		return s.errorResponse(req.ID, -32601, fmt.Sprintf("Method not found: %s", req.Method))
304→	}
305→}
306→
307→// indexExists checks whether the index directory exists
308→func (s *Server) indexExists() bool {
309→	_, err := os.Stat(s.indexDir)
310→	return err == nil
311→}
312→
313→func (s *Server) handleToolCall(id any, params *ToolCallParams) *Response {
314→	var args struct {
315→		Path string `json:"path"`
316→	}
317→	if err := json.Unmarshal(params.Arguments, &args); err != nil {
318→		return s.errorResponse(id, -32602, "Invalid arguments")
319→	}
320→
321→	// Check if index exists before attempting to query
322→	if !s.indexExists() {
323→		return &Response{
324→			JSONRPC: "2.0",
325→			ID:      id,
326→			Result: ToolCallResult{
327→				Content: []ContentItem{{Type: "text", Text: "Index not found. Run 'memo scan' or 'memo watch' first to build the index."}},
328→				IsError: true,
329→			},
330→		}
331→	}
332→
333→	var result any
334→	var err error
335→
336→	switch params.Name {
337→	case "memo_list_keys":
338→		result, err = ListKeys(s.indexDir, args.Path)
339→	case "memo_get_value":
340→		result, err = GetValue(s.indexDir, args.Path)
341→	default:
342→		return s.errorResponse(id, -32602, fmt.Sprintf("Unknown tool: %s", params.Name))
343→	}
344→
345→	if err != nil {
346→		errMsg := err.Error()
347→		if strings.Contains(errMsg, "failed to parse") {
348→			errMsg += "\nThe index file may be corrupted. Try running 'memo scan' to rebuild it."
349→		}
350→		return &Response{
351→			JSONRPC: "2.0",
352→			ID:      id,
353→			Result: ToolCallResult{
354→				Content: []ContentItem{{Type: "text", Text: errMsg}},
355→				IsError: true,
356→			},
357→		}
358→	}
359→
360→	// Check analysis status
361→	var warning string
362→	status := s.getStatus()
363→	if status.Status == "analyzing" {
364→		warning = "Data may be stale: analysis in progress"
365→		if status.Since != nil {
366→			warning += fmt.Sprintf(" (started %s ago)", time.Since(*status.Since).Round(time.Second))
367→		}
368→	}
369→
370→	resultJSON, _ := json.Marshal(result)
371→	return &Response{
372→		JSONRPC: "2.0",
373→		ID:      id,
374→		Result: ToolCallResult{
375→			Content: []ContentItem{{Type: "text", Text: string(resultJSON)}},
376→			Warning: warning,
377→		},
378→	}
379→}
380→
381→func (s *Server) errorResponse(id any, code int, message string) *Response {
382→	return &Response{
383→		JSONRPC: "2.0",
384→		ID:      id,
385→		Error:   &Error{Code: code, Message: message},
386→	}
387→}
388→
389→func (s *Server) sendError(id any, code int, message string) {
390→	s.sendResponse(s.errorResponse(id, code, message))
391→}
392→
393→func (s *Server) sendResponse(resp *Response) {
394→	data, _ := json.Marshal(resp)
395→	fmt.Fprintln(s.writer, string(data))
396→}
397→
398→// Close releases resources held by the server
399→func (s *Server) Close() error {
400→	if s.history != nil {
401→		return s.history.Close()
402→	}
403→	return nil
404→}
405→
406→// Serve starts an MCP server for the given work directory
407→func Serve(workDir string) error {
408→	server := NewServer(workDir)
409→	defer server.Close()
410→	return server.Run()
411→}
