  1→package mcp
  2→
  3→import (
  4→	"encoding/json"
  5→	"fmt"
  6→	"os"
  7→	"path/filepath"
  8→	"strconv"
  9→	"strings"
 10→)
 11→
 12→// PathSegment represents a single segment in a query path
 13→type PathSegment struct {
 14→	Key     string
 15→	Index   int
 16→	IsIndex bool
 17→}
 18→
 19→// ListKeysResult is the result of list_keys operation
 20→type ListKeysResult struct {
 21→	Type   string   `json:"type"`            // "dict" or "list"
 22→	Keys   []string `json:"keys,omitempty"`  // for dict
 23→	Length int      `json:"length,omitempty"` // for list
 24→}
 25→
 26→// GetValueResult is the result of get_value operation
 27→type GetValueResult struct {
 28→	Value string `json:"value"`
 29→}
 30→
 31→// Allowed index files
 32→var allowedFiles = map[string]bool{
 33→	"arch":      true,
 34→	"interface": true,
 35→	"stories":   true,
 36→	"issues":    true,
 37→}
 38→
 39→// ParsePath parses a path like [arch][modules][0][name] into file and segments
 40→// Uses a state machine to handle escaping
 41→func ParsePath(path string) (file string, segments []PathSegment, err error) {
 42→	if len(path) == 0 {
 43→		return "", nil, fmt.Errorf("empty path")
 44→	}
 45→
 46→	var result []PathSegment
 47→	var current strings.Builder
 48→	inBracket := false
 49→	escaped := false
 50→
 51→	for i := 0; i < len(path); i++ {
 52→		c := path[i]
 53→
 54→		if escaped {
 55→			// Handle escape sequences
 56→			switch c {
 57→			case '[', ']', '\\':
 58→				current.WriteByte(c)
 59→			default:
 60→				return "", nil, fmt.Errorf("invalid escape sequence at position %d", i)
 61→			}
 62→			escaped = false
 63→			continue
 64→		}
 65→
 66→		switch c {
 67→		case '\\':
 68→			escaped = true
 69→		case '[':
 70→			if inBracket {
 71→				return "", nil, fmt.Errorf("unexpected '[' at position %d", i)
 72→			}
 73→			inBracket = true
 74→		case ']':
 75→			if !inBracket {
 76→				return "", nil, fmt.Errorf("unexpected ']' at position %d", i)
 77→			}
 78→			inBracket = false
 79→			key := current.String()
 80→			current.Reset()
 81→
 82→			if key == "" {
 83→				return "", nil, fmt.Errorf("empty segment at position %d", i)
 84→			}
 85→
 86→			// Check if it's a numeric index
 87→			if idx, err := strconv.Atoi(key); err == nil && idx >= 0 {
 88→				result = append(result, PathSegment{Index: idx, IsIndex: true})
 89→			} else {
 90→				// Validate key: no control characters
 91→				if err := validateKey(key); err != nil {
 92→					return "", nil, err
 93→				}
 94→				result = append(result, PathSegment{Key: key, IsIndex: false})
 95→			}
 96→		default:
 97→			if !inBracket {
 98→				return "", nil, fmt.Errorf("unexpected character '%c' at position %d", c, i)
 99→			}
100→			current.WriteByte(c)
101→		}
102→	}
103→
104→	if inBracket {
105→		return "", nil, fmt.Errorf("unclosed bracket")
106→	}
107→	if escaped {
108→		return "", nil, fmt.Errorf("trailing escape character")
109→	}
110→	if len(result) == 0 {
111→		return "", nil, fmt.Errorf("no segments in path")
112→	}
113→
114→	// First segment must be the file name
115→	if result[0].IsIndex {
116→		return "", nil, fmt.Errorf("first segment must be file name, not index")
117→	}
118→	file = result[0].Key
119→	if !allowedFiles[file] {
120→		return "", nil, fmt.Errorf("invalid file: %s (allowed: arch, interface, stories, issues)", file)
121→	}
122→
123→	return file, result[1:], nil
124→}
125→
126→// validateKey checks for forbidden characters in keys
127→func validateKey(key string) error {
128→	if len(key) > 100 {
129→		return fmt.Errorf("key too long: %d chars (max 100)", len(key))
130→	}
131→	for i, c := range key {
132→		if c < 32 || c == 127 {
133→			return fmt.Errorf("control character in key at position %d", i)
134→		}
135→	}
136→	return nil
137→}
138→
139→// traverse navigates through the data using segments
140→func traverse(data any, segments []PathSegment) (any, error) {
141→	current := data
142→
143→	for i, seg := range segments {
144→		if seg.IsIndex {
145→			arr, ok := current.([]any)
146→			if !ok {
147→				return nil, fmt.Errorf("segment %d: expected array, got %T", i, current)
148→			}
149→			if seg.Index < 0 || seg.Index >= len(arr) {
150→				return nil, fmt.Errorf("segment %d: index %d out of bounds (length %d)", i, seg.Index, len(arr))
151→			}
152→			current = arr[seg.Index]
153→		} else {
154→			obj, ok := current.(map[string]any)
155→			if !ok {
156→				return nil, fmt.Errorf("segment %d: expected object, got %T", i, current)
157→			}
158→			val, exists := obj[seg.Key]
159→			if !exists {
160→				return nil, fmt.Errorf("segment %d: key '%s' not found", i, seg.Key)
161→			}
162→			current = val
163→		}
164→	}
165→
166→	return current, nil
167→}
168→
169→// loadFile loads and parses a JSON file from the index directory
170→func loadFile(indexDir, file string) (any, error) {
171→	path := filepath.Join(indexDir, file+".json")
172→	data, err := os.ReadFile(path)
173→	if err != nil {
174→		return nil, fmt.Errorf("failed to read %s: %w", path, err)
175→	}
176→
177→	var result any
178→	if err := json.Unmarshal(data, &result); err != nil {
179→		return nil, fmt.Errorf("failed to parse %s: %w", path, err)
180→	}
181→
182→	return result, nil
183→}
184→
185→// ListKeys returns keys/length for the value at the given path
186→func ListKeys(indexDir, path string) (*ListKeysResult, error) {
187→	file, segments, err := ParsePath(path)
188→	if err != nil {
189→		return nil, err
190→	}
191→
192→	data, err := loadFile(indexDir, file)
193→	if err != nil {
194→		return nil, err
195→	}
196→
197→	value, err := traverse(data, segments)
198→	if err != nil {
199→		return nil, err
200→	}
201→
202→	switch v := value.(type) {
203→	case map[string]any:
204→		keys := make([]string, 0, len(v))
205→		for k := range v {
206→			keys = append(keys, k)
207→		}
208→		return &ListKeysResult{Type: "dict", Keys: keys}, nil
209→	case []any:
210→		return &ListKeysResult{Type: "list", Length: len(v)}, nil
211→	default:
212→		return nil, fmt.Errorf("value is not a dict or list, it's %T", value)
213→	}
214→}
215→
216→// GetValue returns the JSON string of the value at the given path
217→func GetValue(indexDir, path string) (*GetValueResult, error) {
218→	file, segments, err := ParsePath(path)
219→	if err != nil {
220→		return nil, err
221→	}
222→
223→	data, err := loadFile(indexDir, file)
224→	if err != nil {
225→		return nil, err
226→	}
227→
228→	value, err := traverse(data, segments)
229→	if err != nil {
230→		return nil, err
231→	}
232→
233→	jsonBytes, err := json.Marshal(value)
234→	if err != nil {
235→		return nil, fmt.Errorf("failed to marshal value: %w", err)
236→	}
237→
238→	return &GetValueResult{Value: string(jsonBytes)}, nil
239→}
