 47→type Analyser struct {
 48→	agentCfg  AgentConfig
 49→	indexDir  string
 50→	workDir   string
 51→	sessionID string
 52→}
 53→
 54→// generateSessionID creates a deterministic session ID based on work directory
 55→// Format: <sessionPrefix><8-char-hash-of-workdir>
 56→func generateSessionID(workDir string) string {
 57→	hash := sha256.Sum256([]byte(workDir))
 58→	shortHash := hex.EncodeToString(hash[:4]) // 8 hex chars
 59→	return sessionPrefix + shortHash
 60→}
 61→
 62→// toRelativePaths converts absolute paths to relative paths based on workDir
 63→func toRelativePaths(files []string, workDir string) []string {
 64→	rel := make([]string, 0, len(files))
 65→	for _, f := range files {
 66→		r, err := filepath.Rel(workDir, f)
 67→		if err != nil {
 68→			r = f
 69→		}
 70→		rel = append(rel, r)
 71→	}
 72→	return rel
 73→}
 74→
 75→// splitIntoBatches splits files into batches by directory when count > threshold
 76→func splitIntoBatches(files []string, threshold int) [][]string {
 77→	if len(files) <= threshold {
 78→		return [][]string{files}
 79→	}
 80→
 81→	// Group by first path component (top-level dir)
 82→	groups := make(map[string][]string)
 83→	for _, f := range files {
 84→		parts := strings.SplitN(f, string(filepath.Separator), 2)
 85→		dir := parts[0]
 86→		groups[dir] = append(groups[dir], f)
 87→	}
 88→
 89→	var batches [][]string
 90→	for dir, dirFiles := range groups {
 91→		if len(dirFiles) <= threshold {
 92→			batches = append(batches, dirFiles)
 93→		} else {
 94→			// Strip prefix, recurse, restore prefix
 95→			var sub []string
 96→			for _, f := range dirFiles {
 97→				if idx := strings.Index(f, string(filepath.Separator)); idx >= 0 {
 98→					sub = append(sub, f[idx+1:])
 99→				} else {
100→					sub = append(sub, f)
101→				}
102→			}
103→			for _, b := range splitIntoBatches(sub, threshold) {
104→				restored := make([]string, len(b))
105→				for i, f := range b {
106→					restored[i] = filepath.Join(dir, f)
107→				}
108→				batches = append(batches, restored)
109→			}
110→		}
111→	}
112→	return batches
113→}
114→
115→// mergeBatches merges small batches into larger ones using First Fit Decreasing algorithm.
116→// This solves the bin packing problem: minimize number of batches while respecting capacity.
117→func mergeBatches(batches [][]string, capacity int) [][]string {
118→	if len(batches) <= 1 {
119→		return batches
120→	}
121→
122→	// Sort batches by size descending (FFD: First Fit Decreasing)
123→	sorted := make([][]string, len(batches))
124→	copy(sorted, batches)
125→	sort.Slice(sorted, func(i, j int) bool {
126→		return len(sorted[i]) > len(sorted[j])
127→	})
128→
129→	var merged [][]string
130→
131→	for _, batch := range sorted {
132→		placed := false
133→
134→		// Try to fit into existing merged batch (First Fit)
135→		for i := range merged {
136→			if len(merged[i])+len(batch) <= capacity {
137→				merged[i] = append(merged[i], batch...)
138→				placed = true
139→				break
140→			}
141→		}
142→
143→		// No fit found, create new batch
144→		if !placed {
145→			newBatch := make([]string, len(batch))
146→			copy(newBatch, batch)
147→			merged = append(merged, newBatch)
148→		}
149→	}
150→
151→	return merged
152→}
153→
154→// NewAnalyser creates a new Analyser instance
155→func NewAnalyser(agentCfg AgentConfig, workDir string) *Analyser {
156→	sessionID := generateSessionID(workDir)
157→	internal.LogInfo("Using session ID: %s for workDir: %s", sessionID, workDir)
158→
159→	return &Analyser{
160→		agentCfg:  agentCfg,
161→		indexDir:  filepath.Join(workDir, ".memo", "index"),
162→		workDir:   workDir,
163→		sessionID: sessionID,
164→	}
165→}
166→
167→// Analyse performs analysis on the given changed files
168→func (a *Analyser) Analyse(ctx context.Context, changedFiles []string) error {
169→	// Convert to relative paths
170→	relFiles := toRelativePaths(changedFiles, a.workDir)
171→
172→	// Split into batches if needed, then merge small batches
173→	batches := splitIntoBatches(relFiles, maxFilesPerBatch)
174→	batches = mergeBatches(batches, maxFilesPerBatch)
175→	internal.LogInfo("Starting analysis for %d files in %d batch(es)", len(changedFiles), len(batches))
176→
177→	// Mark analysis in progress
178→	memoDir := filepath.Dir(a.indexDir)
179→	if err := SetStatus(memoDir, "analyzing"); err != nil {
180→		internal.LogError("Failed to set status: %v", err)
181→	}
182→	defer func() {
183→		if err := SetStatus(memoDir, "idle"); err != nil {
184→			internal.LogError("Failed to clear status: %v", err)
185→		}
186→	}()
187→
188→	// Process each batch
189→	for i, batch := range batches {
190→		if err := a.analyseBatch(ctx, batch, i+1, len(batches)); err != nil {
191→			return fmt.Errorf("batch %d/%d failed: %w", i+1, len(batches), err)
192→		}
193→	}
194→
195→	return nil
196→}
